import {seed,knowledge,fmtDate,fmtFull,fmtTime,slots,nextAction,statusLabel,act,advance,VERSION} from './engine.js';
const STORAGE='cedar-demo-v1';
let state,storageWarning=false;
try{const saved=JSON.parse(localStorage.getItem(STORAGE));state=saved?.version===VERSION&&saved.cases?.length===3?saved:seed();}catch{state=seed();storageWarning=true;}
let query='',filter='all',selectedSlot=null,modal=null,sourceOpen=null;
const icons={patients:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 3H20v19H6.5A2.5 2.5 0 0 1 4 19.5v-14A2.5 2.5 0 0 1 6.5 3Z"/><path d="M8 7h8m-8 4h5"/>',flow:'<rect x="8" y="2" width="8" height="5" rx="1"/><rect x="2" y="17" width="8" height="5" rx="1"/><rect x="14" y="17" width="8" height="5" rx="1"/><path d="M12 7v5M6 17v-5h12v5"/>',arrow:'<path d="m9 5 7 7-7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9H13a8.5 8.5 0 0 1 8 8v.5Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3Z"/>',external:'<path d="M15 3h6v6m0-6L10 14M9 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',shield:'<path d="m12 3 8 4v6c0 5-8 8-8 8s-8-3-8-8V7l8-4Z"/><path d="m8 12 3 3 5-6"/>'};
const ic=(name,cls='')=>`<svg class="icon ${cls}" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>state.cases.find(c=>c.id===state.selected)||state.cases[0];
const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const avatar=c=>`<span class="avatar ${c.color}">${c.initials}</span>`;
const badge=c=>`<span class="badge ${!c.contact?'stopped':c.status}"><i></i>${statusLabel(c)}</span>`;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageWarning=true;}}
function toast(text){if(!text)return;const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function logo(){return `<span class="brand-mark"><svg width="24" height="24" viewBox="0 0 40 40" fill="none"><path d="M29 9H17L9 20l8 11h12M9 20h20" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/></svg></span><span>Cedar<span class="brand-dot">.</span></span>`;}
function sidebar(){return `<aside class="sidebar"><a class="brand" href="#" data-action="home" aria-label="Cedar home">${logo()}</a><div class="practice-label"><span class="practice-symbol">C</span><div>Cedar Dental<small>Care coordination</small></div><span class="online" title="Demo systems connected"></span></div><nav aria-label="Main navigation">${[['patients','patients','Patients'],['knowledge','book','Knowledge base'],['workflow','flow','Agent workflow']].map(([id,icon,title])=>`<button data-action="page" data-value="${id}" class="nav-item ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${ic(icon)}${title}${id==='patients'?`<span class="nav-count">${state.cases.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="connection">${ic('shield')}<div>Systems connected<small>Simulated practice records</small></div></div><div class="profile"><span class="profile-icon">CD</span><div>Practice workspace<small>Interactive demo</small></div></div></div></aside>`;}
function header(){const titles={patients:['Treatment follow-up','Helping patients take the next step in their care.'],knowledge:['Knowledge base','The practice knowledge behind every explanation.'],workflow:['A coordinator that follows through','Context persists. Work resumes when the moment is right.']};return `<header class="page-header"><div><div class="breadcrumb">Cedar Dental <span>/</span> Care coordination</div><h1>${titles[state.page][0]}</h1><p>${titles[state.page][1]}</p></div>${btn(`${ic('message')} Patient view`,'view','secondary','data-value="patient"')}</header>`;}
function stats(){const complete=state.cases.filter(c=>c.sourceStatus==='completed').length,booked=state.cases.filter(c=>c.appointment&&c.sourceStatus!=='completed').length,active=state.cases.filter(c=>c.contact&&!['completed','declined','closed'].includes(c.status)).length;return `<section class="stats" aria-label="Demo outcomes"><div><span>Active coordination</span><strong>${active.toString().padStart(2,'0')}</strong><small>Recommendations in progress</small></div><div><span>Appointments booked</span><strong>${booked.toString().padStart(2,'0')}</strong><small>Confirmed in the practice calendar</small></div><div><span>Treatments completed</span><strong>${complete.toString().padStart(2,'0')}</strong><small>Verified by the practice record</small></div><div class="agent-status">${ic('spark')}<div><strong>Taking care of the follow-up</strong><span>Outreach and scheduling run automatically.</span></div><span class="online"></span></div></section>`;}
function patients(){const list=state.cases.filter(c=>(!query||`${c.name} ${c.treatment}`.toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||(filter==='booked'?c.status==='booked':filter==='completed'?c.status==='completed':['waiting','engaged','paused'].includes(c.status))));return `${stats()}<div class="workspace"><section class="worklist"><div class="section-heading"><div><h2>Patient worklist <span class="muted">${state.cases.length}</span></h2><p>Every recommendation, a clear next step.</p></div></div><div class="list-controls"><label class="search">${ic('search')}<input id="search" aria-label="Search patients" placeholder="Search patients" value="${esc(query)}"></label><select id="filter" aria-label="Filter patient status">${[['all','All statuses'],['active','In progress'],['booked','Booked'],['completed','Completed']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="list-label"><span>Patient & treatment</span><span>Progress</span></div><div class="patient-list">${list.length?list.map(c=>`<button class="patient-row ${state.selected===c.id?'selected':''}" data-action="select" data-value="${c.id}" aria-pressed="${state.selected===c.id}"><div class="patient-line">${avatar(c)}<div class="patient-name"><strong>${c.name}</strong><span>${c.treatment}</span></div>${ic('arrow')}</div><div class="patient-row-bottom">${badge(c)}<span>${c.barrier}</span></div><div class="row-next">${ic('clock')}<span>${nextAction(c)}</span></div></button>`).join(''):`<div class="empty">${ic('search')}<h3>No matching patients</h3><p>Try another name or status.</p>${btn('Clear filters','clear','secondary')}</div>`}</div><div class="list-foot">${ic('shield')} Outreach respects patient choices and contact preferences.</div></section>${detail(current())}</div>`;}
function detail(c){return `<section class="case-panel" aria-label="${c.name} case detail"><div class="case-header"><div class="case-person">${avatar(c)}<div><h2>${c.name}</h2><p>${c.treatment} <span>·</span> Dr. Lee</p></div></div>${badge(c)}</div><div class="tabs" role="tablist" aria-label="Case detail">${[['conversation','Conversation'],['plan','Plan & sources'],['activity','Activity']].map(([id,t])=>`<button role="tab" aria-selected="${state.tab===id}" data-action="tab" data-value="${id}" class="${state.tab===id?'active':''}">${t}${id==='activity'?`<span>${c.events.length}</span>`:''}</button>`).join('')}</div><div class="case-content" role="tabpanel">${state.tab==='conversation'?conversation(c,false):state.tab==='plan'?plan(c):timeline(c)}</div></section>`;}
function conversation(c,isPatient){return `<div class="conversation-info">${ic('shield')} ${isPatient?'Cedar Dental’s automated care coordinator':'Patient conversation · automatic follow-up'}</div><div class="messages" id="messages"><div class="conversation-date">${fmtFull(c.messages[0].at)}</div>${c.messages.map((m,i)=>`<div class="message-row ${m.who}">${m.who==='agent'?'<span class="mini-mark">C</span>':''}<div class="message-wrap"><div class="message">${esc(m.text)}</div>${m.sources.length?`<div class="source-chips">${m.sources.map(id=>`<button data-action="source" data-value="${id}">${ic('book')}${id==='note'?'Clinical note':id==='crown'?'Crown guide':id==='visit'?'Visit guide':'Scheduling'}</button>`).join('')}</div>`:''}<span class="message-time">${m.who==='agent'?'Care coordinator':'You'} · ${fmtDate(m.at)}, ${fmtTime(m.at)}</span></div></div>`).join('')}</div>${appointment(c)}<div class="reply-area">${isPatient?'':`<div class="reply-caption">${ic('message')} Try the patient’s response <span>Demo</span></div>`}${choices(c)}</div>`;}
function appointment(c){if(!c.appointment)return '';const a=c.appointment;return `<div class="appointment ${c.sourceStatus==='completed'?'finished':''}"><span class="appointment-icon">${ic(c.sourceStatus==='completed'?'check':'calendar')}</span><div><strong>${c.sourceStatus==='completed'?'Treatment complete':a.kind==='Discussion'?'Discussion confirmed':'Appointment confirmed'}</strong><span>${fmtFull(a.start)} · ${fmtTime(a.start)}</span><small>${a.provider} · ${a.duration} min · Cedar Dental</small></div>${c.sourceStatus!=='completed'?ic('check'):''}</div>`;}
function choices(c){if(!c.contact||['completed','declined','closed'].includes(c.status))return `<div class="closed-state">${ic('check')}<div><strong>${c.sourceStatus==='completed'?'Care completed':!c.contact?'Messages stopped':c.status==='declined'?'Your decision is respected':'Follow-up concluded'}</strong><span>${c.sourceStatus==='completed'?'The practice record confirms completion.':c.appointment?'Your existing appointment remains booked.':'You can contact Cedar Dental directly whenever you need.'}</span></div></div>`;
 const action=(t,a,cls='')=>btn(t,'reply',cls,`data-value="${a}"`);
 let html='';
 if(c.stage==='slots')html=`<div class="slot-heading"><strong>${c.consult?'Discuss your recommendation':'Find a time that works'}</strong><span>${c.consult?'30':'60'} minutes · ${c.consult?'Dr. Shah':'Dr. Lee'}</span></div><div class="slot-list">${slots(state,c).map(x=>`<button class="slot ${selectedSlot===x.id?'chosen':''}" data-action="slot" data-value="${x.id}" aria-pressed="${selectedSlot===x.id}"><span>${fmtFull(x.start)}</span><strong>${fmtTime(x.start)}</strong>${selectedSlot===x.id?ic('check'):''}</button>`).join('')}</div>${btn(c.appointment?'Confirm new appointment':'Confirm appointment','book','primary full',selectedSlot?'':'disabled')}`;
 else if(c.stage==='booked')html=`<div class="reply-buttons">${action('Change appointment','slots')}${btn('Cancel appointment','cancel','')}</div>`;
 else if(c.stage==='paused')html=`<div class="pause-note">${ic('clock')} Follow-up scheduled for ${fmtFull(c.wakeAt)}</div><div class="reply-buttons">${action('I’m ready now','slots','primary')}</div>`;
 else if(c.stage==='cancelled')html=`<div class="reply-buttons">${action('Find another time','slots','primary')}${action('Contact me next week','pause')}</div>`;
 else if(c.stage==='explained')html=`<div class="reply-buttons">${c.id!=='alex'?action('Find a time','slots','primary'):''}${action('Discuss with the dentist','consult',c.id==='alex'?'primary':'')}${action('What happens at the visit?','visit')}</div>`;
 else html=`<div class="reply-buttons">${action('Why was this recommended?','why')}${action('Find a time','slots','primary')}${action('Contact me next week','pause')}</div>`;
 html+=`<details class="patient-options"><summary>More choices</summary><div>${!c.appointment&&c.stage!=='paused'?action('Contact me next week','pause'):''}${!c.appointment?action('I don’t want to proceed','decline'):''}${btn('Stop messages','stop','quiet-danger')}</div></details>`;return html;
}
function plan(c){return `<div class="plan-content"><div class="plan-title">${ic('calendar')}<div><h3>Current recommendation</h3><p>${c.treatment}</p></div><span class="badge ${c.sourceStatus==='completed'?'completed':'waiting'}">${c.sourceStatus==='completed'?'Complete':'Outstanding'}</span></div><dl><div><dt>Recommended by</dt><dd>Dr. Lee · Oct 9, 2026</dd></div><div><dt>Patient’s barrier</dt><dd>${c.barrier}</dd></div><div><dt>Next action</dt><dd>${nextAction(c)}</dd></div><div><dt>Contact preference</dt><dd>${c.contact?'Text follow-up allowed':'Opted out'}</dd></div></dl><h3>From the clinical record</h3><blockquote>${esc(c.note)}</blockquote><p class="small muted">Fictional patient record. The coordinator explains this recommendation; it does not create one.</p><h3>Supporting knowledge</h3>${knowledge.map(k=>`<button class="source-row" data-action="source" data-value="${k.id}">${ic('book')}<span><strong>${k.title}</strong><small>${k.source}</small></span>${ic('arrow')}</button>`).join('')}${appointment(c)}</div>`;}
function timeline(c){return `<div class="timeline"><p class="small muted">A record of autonomous actions and the context behind them.</p>${[...c.events].reverse().map(e=>`<article><span class="timeline-dot"></span><time>${fmtFull(e.at)} · ${fmtTime(e.at)}</time><h3>${e.title}</h3><p>${esc(e.detail)}</p></article>`).join('')}<div class="timeline-origin">Recommendation received from the practice system</div></div>`;}
function library(){return `<div class="knowledge-layout"><section><div class="knowledge-intro"><span class="large-icon">${ic('book')}</span><div><h2>Clear answers, grounded in the record.</h2><p>Practice-approved guidance explains the treatment. The clinical note explains why it was recommended to this patient.</p></div></div><div class="knowledge-table"><div class="knowledge-table-head">Practice knowledge <span>${knowledge.length} entries</span></div>${knowledge.map(k=>`<button class="knowledge-entry" data-action="source" data-value="${k.id}"><span class="document-icon">${ic('book')}</span><div><span class="category">${k.category}</span><h3>${k.title}</h3><p>${k.source} · Updated ${k.updated}</p></div>${ic('arrow')}</button>`).join('')}</div><h2 class="context-title">Patient-specific context</h2><div class="context-grid">${state.cases.map(c=>`<button class="context-card" data-action="openplan" data-value="${c.id}"><div>${avatar(c)}<strong>${c.name}</strong>${ic('arrow')}</div><p>${esc(c.note)}</p><span>View recommendation and sources</span></button>`).join('')}</div></section><aside class="knowledge-aside"><span class="subtle-symbol">${ic('shield')}</span><h3>Know what the record can answer.</h3><p>Every explanation has a source. When the patient’s question goes beyond that source, the coordinator offers a dentist discussion.</p><div><strong>Connected context</strong><ul><li>Treatment plans & clinical notes</li><li>Appointment availability</li><li>Patient contact preferences</li><li>Treatment completion records</li></ul></div><small>All records and connections are simulated for this demonstration.</small></aside></div>`;}
function workflow(){const c=current();return `<section class="workflow-intro"><span class="large-icon">${ic('flow')}</span><div><h2>The task stays open until the care is complete.</h2><p>A reply, a date, or a change in the practice record brings the coordinator back—with its context intact.</p></div></section><div class="flow-steps">${[['Observe','Read the current recommendation, appointments, and preferences.'],['Decide','Choose the next action grounded in the record.'],['Act','Explain, offer appointments, or schedule follow-up.'],['Remember','Keep the patient’s choices and next action.'],['Resume','Wake on a reply, requested date, or practice event.'],['Close','Verify completion or respect a decision to stop.']].map(([h,p],i)=>`<div class="flow-step"><span>${i+1}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><div class="workflow-bottom"><section class="memory"><div class="section-heading"><h2>What the coordinator remembers</h2><select id="memory-patient" aria-label="Inspect patient memory">${state.cases.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${x.name}</option>`).join('')}</select></div><dl><div><dt>Patient & recommendation</dt><dd>${c.name} · ${c.treatment}</dd></div><div><dt>Current barrier</dt><dd>${c.barrier}</dd></div><div><dt>State</dt><dd>${statusLabel(c)}</dd></div><div><dt>Next action</dt><dd>${nextAction(c)}</dd></div><div><dt>Conversation retained</dt><dd>${c.messages.length} messages</dd></div><div><dt>Contact permission</dt><dd>${c.contact?'Allowed':'Stopped'}</dd></div></dl>${btn('Open patient case','select','secondary',`data-value="${c.id}"`)}</section><section class="guardrails"><h2>Autonomous, with clear boundaries</h2>${[['Source before explanation','Use the existing recommendation; disclose missing information.'],['Patient choice before booking','Confirm the selected time. Honor pauses and stop requests.'],['Recheck before acting','Avoid stale appointments, duplicate messages, and unnecessary outreach.'],['Completion before closure','A booked or attended visit is not completed treatment.']].map(([a,b])=>`<div>${ic('check')}<p><strong>${a}</strong><span>${b}</span></p></div>`).join('')}<p class="small muted">This prototype uses deterministic events and scripted responses. No live AI or external systems are called.</p></section></div>`;}
function patientView(){const c=current();return `<div class="patient-shell"><header class="patient-top"><a href="#" data-action="home" class="brand">${logo()}</a>${btn('Back to practice','view','secondary','data-value="admin"')}</header><div class="patient-demo-label"><span class="demo-pill">Patient preview</span><select id="patient-select" aria-label="Preview as patient">${state.cases.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${x.name}</option>`).join('')}</select><span>Fictional conversation</span></div><main class="patient-phone"><header><span class="phone-brand">C</span><div><h1>Cedar Dental</h1><p>Care coordinator</p></div>${ic('shield')}</header>${conversation(c,true)}</main><p class="patient-disclaimer">Scripted, text-only demo. No real messages or appointments.</p></div>`;}
function toolbar(){const c=current();return `<div class="demo-toolbar"><div class="demo-clock"><span class="demo-pill">Interactive demo</span><span>${ic('clock')} ${fmtFull(state.now)} <small>Practice time</small></span></div><div class="demo-actions">${btn(`${ic('clock')} Advance time`,'advance','toolbar-btn','title="Jump to the next scheduled follow-up"')}${btn('Simulate cancellation','cancel','toolbar-btn',c.appointment&&c.sourceStatus!=='completed'?'':'disabled')}${btn(`${ic('check')} Record completion`,'complete','toolbar-btn',c.appointment?.kind==='Treatment'&&c.sourceStatus!=='completed'?'':'disabled')}${btn(ic('reset'),'reset','icon-btn','aria-label="Reset demo" title="Reset demo"')}</div></div>`;}
function render(){const active=document.activeElement?.id;const position=active==='search'?document.activeElement.selectionStart:null;document.querySelector('#app').innerHTML=`${state.view==='patient'?patientView():`${sidebar()}<main class="main">${header()}${state.page==='patients'?patients():state.page==='knowledge'?library():workflow()}</main>`}${storageWarning?'<div class="storage-warning">Browser storage is unavailable. Progress will reset on refresh.</div>':''}${toolbar()}${modalMarkup()}`;save();if(active==='search'){const el=document.getElementById('search');el?.focus();el?.setSelectionRange(position,position);}if(modal){const dialog=document.querySelector('dialog');dialog.showModal();dialog.querySelector('button')?.focus();}else{const messages=document.querySelector('#messages');if(messages)messages.scrollTop=messages.scrollHeight;}}
function modalMarkup(){if(!modal)return '';if(modal==='source'){const c=current(),k=sourceOpen==='note'?{title:'Clinical note',category:c.name,source:'Simulated practice record',updated:'Oct 9, 2026',text:c.note}:knowledge.find(x=>x.id===sourceOpen);return `<dialog aria-labelledby="modal-title"><div class="modal-top"><span>${ic('book')} Source detail</span>${btn(ic('close'),'dismiss','icon-btn','aria-label="Close source"')}</div><span class="category">${k.category}</span><h2 id="modal-title">${k.title}</h2><p class="source-text">${esc(k.text)}</p><div class="source-meta"><strong>${k.source}</strong><span>Updated ${k.updated}</span><span>Sample content for this prototype</span></div>${btn('Done','dismiss','primary full')}</dialog>`;}
 const config={reset:['Reset the demo?','All three patient cases, conversations, and the practice clock will return to their starting state.','Reset demo'],cancel:['Cancel this appointment?','The slot will be released. The coordinator will help the patient choose a new time or pause follow-up.','Cancel appointment'],stop:['Stop coordinator messages?','Future outreach will stop. Any existing appointment stays booked.','Stop messages']}[modal];return `<dialog aria-labelledby="modal-title"><h2 id="modal-title">${config[0]}</h2><p>${config[1]}</p><div class="modal-actions">${btn('Go back','dismiss','secondary')}${btn(config[2],'confirm','primary')}</div></dialog>`;}
let returnFocus=null;
function openModal(name){returnFocus=document.activeElement;modal=name;render();}
function closeModal(){modal=null;render();const action=returnFocus?.dataset.action;const value=returnFocus?.dataset.value;if(action)document.querySelector(`[data-action="${action}"]${value?`[data-value="${value}"]`:''}`)?.focus();}
function run(type,payload){const result=act(state,state.selected,type,payload);selectedSlot=null;render();toast(result.message);return result;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action,v=b.dataset.value;
 if(a==='page'){state.page=v;state.view='admin';render();}
 else if(a==='home'){state.page='patients';state.view='admin';render();}
 else if(a==='view'){state.view=v;render();}
 else if(a==='select'||a==='openplan'){state.selected=v;state.page='patients';state.tab=a==='openplan'?'plan':'conversation';selectedSlot=null;render();}
 else if(a==='tab'){state.tab=v;render();}
 else if(a==='reply')run(v);
 else if(a==='slot'){selectedSlot=v;render();document.querySelector('[data-action="book"]')?.focus();}
 else if(a==='book')run('book',selectedSlot);
 else if(a==='advance'){selectedSlot=null;const msg=advance(state);render();toast(msg);}
 else if(a==='complete')run('complete');
 else if(['reset','cancel','stop'].includes(a))openModal(a);
 else if(a==='source'){sourceOpen=v;openModal('source');}
 else if(a==='dismiss')closeModal();
 else if(a==='confirm'){const pending=modal;modal=null;if(pending==='reset'){state=seed();filter='all';query='';selectedSlot=null;render();toast('Demo reset. Initial outreach sent automatically.');}else run(pending);}
 else if(a==='clear'){query='';filter='all';render();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render();}else if(['patient-select','memory-patient'].includes(e.target.id)){state.selected=e.target.value;selectedSlot=null;render();}});
document.addEventListener('cancel',e=>{if(e.target.tagName==='DIALOG'){e.preventDefault();closeModal();}},true);
render();
